import{_ as n,C as r,o as i,c as s,j as d,a as e,E as o,aj as c}from"./chunks/framework.m090XgxO.js";const q=JSON.parse('{"title":"FloatButton","description":"","frontmatter":{},"headers":[],"relativePath":"components/float-button.md","filePath":"components/float-button.md","lastUpdated":1789206102000}'),h={name:"components/float-button.md"},b={id:"floatbutton",tabindex:"-1"};function u(p,t,g,f,x,m){const l=r("Badge"),a=r("XhDemo");return i(),s("div",null,[d("h1",b,[t[0]||(t[0]=e("FloatButton ",-1)),o(l,{type:"info",text:"浮动按钮"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#floatbutton","aria-label":'Permalink to "FloatButton <Badge type="info" text="浮动按钮" />"'},"​",-1))]),t[3]||(t[3]=c('<p>钉在视口某一角的动作入口：平时是一枚触发器，展开后长出一列动作。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/float-button" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/float-button.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/float-button" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/float-button" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/float-button.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>点触发器展开一组动作，再点一下收起；收起时那组按钮退出 Tab 序列</p>',4)),o(a,{src:"float-button/01-basic"}),t[4]||(t[4]=d("h2",{id:"示例",tabindex:"-1"},[e("示例 "),d("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=d("h3",{id:"四角",tabindex:"-1"},[e("四角 "),d("a",{class:"header-anchor",href:"#四角","aria-label":'Permalink to "四角"'},"​")],-1)),t[6]||(t[6]=d("p",null,"placement 决定钉在哪一角，start / end 跟着书写方向走；那一组恒往页面中间长",-1)),o(a,{src:"float-button/02-placement"}),t[7]||(t[7]=d("h3",{id:"展开方式",tabindex:"-1"},[e("展开方式 "),d("a",{class:"header-anchor",href:"#展开方式","aria-label":'Permalink to "展开方式"'},"​")],-1)),t[8]||(t[8]=d("p",null,"hover 指针进出整个壳就开合，click 点触发器；点这条恒在，触摸与键盘都靠它",-1)),o(a,{src:"float-button/03-expand-trigger"}),t[9]||(t[9]=d("h3",{id:"外形与贴边",tabindex:"-1"},[e("外形与贴边 "),d("a",{class:"header-anchor",href:"#外形与贴边","aria-label":'Permalink to "外形与贴边"'},"​")],-1)),t[10]||(t[10]=d("p",null,"shape 换圆角档，offset 决定距那两条边多远；translations 换掉读屏念出的名字",-1)),o(a,{src:"float-button/04-shape-offset"}),t[11]||(t[11]=d("h3",{id:"形态与尺寸",tabindex:"-1"},[e("形态与尺寸 "),d("a",{class:"header-anchor",href:"#形态与尺寸","aria-label":'Permalink to "形态与尺寸"'},"​")],-1)),t[12]||(t[12]=d("p",null,"variant 换触发器的用色方式，size 换直径；缺省档与 lg 同高，悬浮钮起步就比行内按钮大一号",-1)),o(a,{src:"float-button/05-variant-size"}),t[13]||(t[13]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>页面主动作在长内容里滚没了，但要求随时可达（新建、回到编辑、联系客服）。</li><li>移动端或窄视口，工具栏没有位置再挂按钮。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>动作与当前滚动位置有关：那是<a href="./back-top">回到顶部</a>。</li><li>一屏里已经有固定工具栏：直接放进<a href="./toolbar">工具栏</a>，别再叠一层浮层。</li><li>动作超过五六个：收进<a href="./menu">菜单</a>或抽屉，一列悬浮按钮遮内容。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>四个角可钉，<code>start</code> / <code>end</code> 跟着书写方向走，那一组恒往页面中间长。</li><li><code>hover</code> 与 <code>click</code> 两种展开方式，点击那条恒在——触摸与键盘只有它。</li><li>click 展开后，层外按下或全局 Escape 会收起；多个浮层并存时只由同一 Document 的逻辑栈顶响应，后开的 Drawer / Popover 先退场。Toast 属于反馈通道，不登记为可消解父层。</li><li>hover 模式保留整个根节点的指针进出路径；指针离开与层外消解同时到达时只发一次关闭意图。</li><li>收起时组内按钮退出 Tab 序列，不会盲聚焦到看不见的东西上。</li><li>缺省触发器是 M3 通透玻璃：背景、边缘、高光、柔影和磨砂来自同一份 <code>material.glass</code> 配方；显式 <code>variant</code> 仍按各自语义表面绘制。</li><li>键盘聚焦时触发器改用配方的实体 focus surface，让公共焦点环不依赖背后页面颜色；高对比、减少透明和强制色沿同一令牌通道降级。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-float-button&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhFloatButtonList</code> <code>XhFloatButtonRoot</code> <code>XhFloatButtonTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useFloatButton</code></td></tr><tr><td>状态机</td><td><code>floatButtonMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/float-button.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;float-button&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong> · <strong><code>list</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只作用于排版；作者没给就不写。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>expandTrigger</code></td><td><code>FloatButtonExpandTrigger</code></td><td></td><td>展开方式，默认 click。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td>距那两条边的距离（px），默认 24。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: CollapsibleOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>FloatButtonPlacement</code></td><td></td><td>钉在哪一角，默认 bottom-end。</td></tr><tr><td><code>shape</code></td><td><code>FloatButtonShape</code></td><td></td><td>触发器外形，默认 circle。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，缺省与 lg 同档——悬浮钮要够得着，起步就比行内按钮大一号。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;FloatButtonTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>ActionVariant</code></td><td></td><td>形态：solid / subtle / outline / ghost，决定底色、描边与前景怎么用。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>CollapsibleOpenChangeDetails</code></td><td>展开状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhFloatButtonRoot</code></td><td><code>default</code></td><td><code>FloatButtonRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>list</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>TOGGLE</code> · <code>DISABLE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isDisabled</code> · <code>isOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useFloatButton</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td>展开的那一组此刻露不露面。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger, not disabled</td><td>展开 / 收起 list；悬停展开时这条路照样在，触摸与键盘都靠它</td></tr><tr><td><code>Escape</code></td><td>open，无论焦点是否仍在整组内</td><td>只收起当前 LayerRegistry 的栈顶层；更晚打开的 Drawer / Popover 先处理自己的 Escape</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open</td><td>走进展开的那一组；收起时 list 带 hidden，里面的按钮一并退出 Tab 序列</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>list</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-label</code></td><td>props.translations?.trigger</td></tr><tr><td><code>list</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/float-button.css</code> 按部件选择：<code>[data-scope=&quot;float-button&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>root</code></td><td><code>data-shape</code></td><td>props.shape</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-shape</code></td><td>props.shape</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>list</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>list</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-float-button-bg</code></td><td><code>trigger</code></td><td><code>background-color</code></td><td><code>default</code></td><td><code>--xh-_float-button-bg</code></td><td>float-button 的 trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-float-button-bg-active</code></td><td><code>trigger</code></td><td><code>background-color</code></td><td><code>active</code><br><code>disabled</code><br><code>not([data-disabled])</code></td><td><code>--xh-_float-button-bg-active</code></td><td>float-button 的 trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-float-button-bg-hover</code></td><td><code>trigger</code></td><td><code>background-color</code></td><td><code>@media (hover: hover)</code><br><code>disabled</code><br><code>hover</code><br><code>not([data-disabled])</code></td><td><code>--xh-_float-button-bg-hover</code></td><td>float-button 的 trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-float-button-border</code></td><td><code>trigger</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-_float-button-border</code></td><td>float-button 的 trigger 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-float-button-border-hover</code></td><td><code>trigger</code></td><td><code>border-color</code></td><td><code>@media (hover: hover)</code><br><code>disabled</code><br><code>hover</code><br><code>not([data-disabled])</code></td><td><code>--xh-_float-button-border-hover</code></td><td>float-button 的 trigger 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-float-button-fg</code></td><td><code>root</code><br><code>trigger</code></td><td><code>--xh-_ring-color</code><br><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>variant=solid</code></td><td><code>--xh-_float-button-fg</code></td><td>float-button 的 root、trigger 部件 --xh-_ring-color、color 覆盖槽。</td></tr><tr><td><code>--xh-float-button-gap</code></td><td><code>list</code><br><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>float-button 的 list、root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-float-button-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-glyph-size-text</code></td><td>float-button 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-float-button-layer</code></td><td><code>root</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-_layer</code></td><td>float-button 的 root 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-float-button-radius</code></td><td><code>list</code><br><code>root</code><br><code>trigger</code></td><td><code>border-radius</code></td><td><code>default</code><br><code>shape=square</code></td><td><code>--xh-shape-control</code><br><code>--xh-shape-pill</code></td><td>float-button 的 list、root、trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-float-button-shadow</code></td><td><code>trigger</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-_float-button-shadow</code></td><td>float-button 的 trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-float-button-size</code></td><td><code>list</code><br><code>trigger</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_float-button-size</code></td><td>float-button 的 list、trigger 部件 block-size、inline-size 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> 随皮肤自带，不引用别处文件里的名字；<code>background</code> · <code>border-color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤另按输入能力分档：<code>hover: hover</code> · <code>pointer: coarse</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>组内放<a href="./button">按钮</a>或<a href="./icon-wrapper">图标块</a>；每一项配<a href="./tooltip">文字提示</a>说明它是什么。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>每一项都给可及名字：悬浮按钮通常只有图标。</li><li><code>offset</code> 要躲开移动端的安全区与系统手势条。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它承载破坏性动作（删除、清空）：贴边的大按钮最容易误触。</li><li>展开后盖住页面主内容或另一个固定条。</li></ul>',57))])}const P=n(h,[["render",u]]);export{q as __pageData,P as default};
